from collections import deque

def valid_parentheses(s: str) -> bool:
    """Return True if the brackets ()[]{} in s are properly matched and nested."""
    stack = deque()
    for char in s:
        if char in ['(', '[', '{']:
            stack.append(char)
        elif char in [')', ']', '}']:
            if not stack:
                return False
            if stack.pop() != char:
                return False
    return not stack

# Test cases
print(valid_parentheses('()'))   # True
print(valid_parentheses('()[]{}')) # True
print(valid_parentheses('(]'))   # False
print(valid_parentheses('{[]}')) # True
