def valid_parentheses(s: str) -> bool:
    """Return True if the brackets ()[]{} in s are properly matched and nested."""
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        # If balance goes negative, it means there's a closing bracket without a matching opening one
        if balance < 0:
            return False
    # If balance is zero, all opening brackets have matching closing brackets
    return balance == 0
