def valid_parentheses(s: str) -> bool:
    from collections import deque

    # Use a deque to simulate a stack
    stack = deque()

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
        elif char == '[':
            stack.append(char)
        elif char == ']':
            if not stack:
                return False
            stack.pop()
        elif char == '{':
            stack.append(char)
        elif char == '}':
            if not stack:
                return False
            stack.pop()

    # If the stack is empty, all opening brackets had matching closing brackets
    return len(stack) == 0
